import{A as a}from"./chunks/AppRelease.D5LKgzZu.js";import{o as t,c as l,a3 as r,E as s}from"./chunks/framework.uXkeDuFE.js";const c=JSON.parse('{"title":"下载与安装","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/install.md","filePath":"zh/guide/install.md","lastUpdated":1790267287000}'),o={name:"zh/guide/install.md"},h=Object.assign(o,{setup(i){return(d,e)=>(t(),l("div",null,[e[0]||(e[0]=r('<h1 id="下载与安装" tabindex="-1">下载与安装 <a class="header-anchor" href="#下载与安装" aria-label="Permalink to &quot;下载与安装&quot;">​</a></h1><h3 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to &quot;系统要求&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">平台</th><th style="text-align:left;">最低要求</th></tr></thead><tbody><tr><td style="text-align:left;">Android</td><td style="text-align:left;">Android 7.0 (API level 24)</td></tr><tr><td style="text-align:left;">iOS</td><td style="text-align:left;">iOS 15.0</td></tr><tr><td style="text-align:left;">Windows</td><td style="text-align:left;">Windows 10, x64</td></tr><tr><td style="text-align:left;">macOS</td><td style="text-align:left;">macOS 12.0</td></tr><tr><td style="text-align:left;">Linux</td><td style="text-align:left;">Debian 10, x64 <sup>1</sup></td></tr><tr><td style="text-align:left;">Web(海外)<sup>3</sup></td><td style="text-align:left;"><a href="https://chaldea.center" target="_blank" rel="noreferrer">https://chaldea.center</a></td></tr><tr><td style="text-align:left;">Web(国内)</td><td style="text-align:left;"><a href="https://cn.chaldea.center" target="_blank" rel="noreferrer">https://cn.chaldea.center</a></td></tr></tbody></table><blockquote><p><sup>1</sup> 仅 Debian 发行版的 Linux 得到测试与支持。虽然可能能运行在其他发行版上，但我们目前无法保证完全兼容，也无法为这些平台出现的问题提供技术支持</p><p><sup>2</sup> <strong>移动端网页</strong>的性能、兼容性较差，不建议使用。自2.5.0起，web版要求在较新版本的浏览器上运行：Chrome/Edge/Firefox 最新 2 个版本、Safari 15.6 及以上。 详见<a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/WeakRef/WeakRef#browser_compatibility" target="_blank" rel="noreferrer">WeakRef</a> 和 <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/globalThis#browser_compatibility" target="_blank" rel="noreferrer">globalThis</a></p></blockquote><p>更多关于系统版本要求可查看<a href="https://docs.flutter.dev/reference/supported-platforms" target="_blank" rel="noreferrer">Flutter 文档</a></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>由于数据储存位置共享，请勿同时运行多个实例或网页，否则会导致数据相互覆盖。</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>若遇到安装/启动问题，请先检查<a href="#注意事项">安装注意事项</a>。</p></div><h2 id="下载" tabindex="-1">下载 <a class="header-anchor" href="#下载" aria-label="Permalink to &quot;下载&quot;">​</a></h2><h3 id="google-play" tabindex="-1">Google Play <a class="header-anchor" href="#google-play" aria-label="Permalink to &quot;Google Play&quot;">​</a></h3><p><a href="https://play.google.com/store/apps/details?id=cc.narumi.chaldea" target="_blank" rel="noreferrer"><img alt="Get it on Google Play" src="https://play.google.com/intl/en_us/badges/static/images/badges/en_badge_web_generic.png" width="137.5"></a><a href="https://f-droid.org/packages/cc.narumi.chaldea.fdroid/" target="_blank" rel="noreferrer"><img alt="Get it on F-droid" src="https://fdroid.gitlab.io/artwork/badge/get-it-on.png" width="137.5"></a></p><p><a href="https://play.google.com/store/apps/details?id=cc.narumi.chaldea" target="_blank" rel="noreferrer">Get it on Google Play</a></p><h3 id="app-store" tabindex="-1">App Store <a class="header-anchor" href="#app-store" aria-label="Permalink to &quot;App Store&quot;">​</a></h3><p><a href="https://apps.apple.com/us/app/chaldea/id1548713491?itsct=apps_box&amp;itscg=30200" target="_blank" rel="noreferrer"><img src="https://tools.applemediaservices.com/api/badges/download-on-the-app-store/black/en-US?size=250x83&amp;releaseDate=1610841600&amp;h=cb0adac232fdd6b88894f78b2f349b6e" alt="Download on the App Store" width="120"></a></p><p><a href="https://apps.apple.com/us/app/chaldea/id1548713491?itsct=apps_box&amp;itscg=30200" target="_blank" rel="noreferrer">Download on the App Store</a></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>包括 iOS App Store 和 Mac App Store</p></div><h3 id="github-release" tabindex="-1">GitHub Release <a class="header-anchor" href="#github-release" aria-label="Permalink to &quot;GitHub Release&quot;">​</a></h3><p>包含 Android、Windows 和 Linux 安装包。若最新版不包含所需平台，请检查更早的发布版本。</p><ul><li><a href="https://github.com/chaldea-center/chaldea/releases" target="_blank" rel="noreferrer">Github Releases</a></li><li><a href="#releases">历史版本</a> 可选代理下载</li></ul><h2 id="upgrade" tabindex="-1">升级 <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;升级 {#upgrade}&quot;">​</a></h2><p><strong>本章主要针对 Windows / Linux 桌面版</strong>，自动升级、手动升级与回滚详见下文小节。macOS 和 Android 的升级比较简单：</p><ul><li><strong>macOS</strong>：通过 App Store 更新。</li><li><strong>Android</strong>：通过应用商店更新，或下载新 APK 覆盖安装，无需卸载旧版。</li></ul><p>桌面版的用户数据保存在程序目录下的 <code>userdata</code> 文件夹中，升级和卸载都不会触碰该目录；手动备份只需复制该文件夹。</p><h3 id="auto-upgrade" tabindex="-1">应用内自动升级 <a class="header-anchor" href="#auto-upgrade" aria-label="Permalink to &quot;应用内自动升级 {#auto-upgrade}&quot;">​</a></h3><p>应用启动时会自动检查新版本，也可在「设置 → 关于 → 检查更新」手动检查。点击「更新」后，应用将自动完成：下载 → 完整性校验 → 备份旧版本 → 替换文件 → 重启。</p><ul><li>升级前旧版本程序文件会自动备份到程序目录下的 <code>_backups/chaldea-backup-&lt;版本号&gt;/</code>（默认保留最近 3 个）。</li><li>下载完成后会暂停并请求确认安装，选择「稍后」可继续使用当前版本，已下载的安装包会保留，无需重新下载。</li><li>自动升级不会修改 <code>userdata</code> 中的用户数据。为防意外（如断电、磁盘故障），建议升级前将 <code>userdata</code> 文件夹复制到其他位置备份。</li></ul><h3 id="manual-upgrade" tabindex="-1">手动升级 <a class="header-anchor" href="#manual-upgrade" aria-label="Permalink to &quot;手动升级 {#manual-upgrade}&quot;">​</a></h3><ol><li>从发布页下载对应平台的新版压缩包。</li><li>删除（或移走）旧程序目录中除 <code>userdata</code> 和 <code>_backups</code> 外的全部文件。</li><li>将新压缩包解压到同一程序目录。</li><li>运行主程序并确认版本号已更新。Linux 下若提示 <code>Permission denied</code>，请在终端执行 <code>chmod +x chaldea</code> 添加可执行权限。</li></ol><h3 id="rollback" tabindex="-1">回滚 <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;回滚 {#rollback}&quot;">​</a></h3><ul><li><p><strong>自动回滚</strong>：升级过程中断（如断电、磁盘错误）时，升级脚本会自动恢复旧版本并重新启动，无需人工处理。</p></li><li><p><strong>手动恢复</strong>：进入 <code>_backups</code> 文件夹，打开想要恢复的 <code>chaldea-backup-&lt;版本号&gt;</code> 文件夹：</p><ul><li>Windows：右键 <code>restore.ps1</code>，选择「使用 PowerShell 运行」；</li><li>Linux：在终端执行 <code>sh restore.sh</code>。</li></ul><p>脚本会将该版本恢复到程序目录并启动。恢复只覆盖程序文件，<code>userdata</code> 不受影响。</p></li></ul><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><h3 id="android" tabindex="-1">Android <a class="header-anchor" href="#android" aria-label="Permalink to &quot;Android&quot;">​</a></h3><p>对于 v2，所有 Android 版本均合并到一个安装包中，因此下载时无需分辨 arm64-v8a、armeabi-v7a、x86_64</p><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Windows 压缩包，请解压后再运行，并储存于非系统目录。<code>Program Files</code>、<code>C:\\</code> 等系统目录需要管理员权限，将导致程序无法保存数据和自动升级。</p></div><h4 id="error-vcruntime140-1-dll-was-not-found" tabindex="-1">Error: <code>VCRUNTIME140_1.dll was not found</code> <a class="header-anchor" href="#error-vcruntime140-1-dll-was-not-found" aria-label="Permalink to &quot;Error: `VCRUNTIME140_1.dll was not found`&quot;">​</a></h4><p>近期版本的压缩包已内置 <code>vcruntime140.dll</code> 等运行库，正常解压后一般不会出现该错误。若仍提示缺失，请安装<a href="https://support.microsoft.com/en-us/help/2977003/the-latest-supported-visual-c-downloads" target="_blank" rel="noreferrer">Microsoft Visual C++ redistributable package</a></p><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>macOS 现在仅提供应用商店版本</p></div><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><p>如果应用启动失败，请尝试从 Terminal 中启动<code>./chaldea</code>并检查可能输出的报错信息。</p><p>自 v2.3.0 起，桌面应用支持在系统托盘显示（默认关闭，可在应用内显示设置中开启），在 Linux 系统中需要<code>libappindicator</code>相关库。如果系统未内置或未安装，则应用启动时可能会失败而无错误提示。若开启托盘后应用崩溃，可在显示设置中关闭「系统托盘」；若已无法进入应用，则删除<code>userdata/user/settings.json</code>中的<code>&quot;showSystemTray&quot;: true</code>设置项（不了解 json 格式可直接删除整个文件）以重置该设置。</p><p>以 Debian 系列为例（如 Ubuntu），可以通过以下命令安装上述库：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libayatana-appindicator3-dev</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> appindicator3-0.1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libappindicator3-dev</span></span></code></pre></div><h2 id="releases" tabindex="-1">历史版本 <a class="header-anchor" href="#releases" aria-label="Permalink to &quot;历史版本 {#releases}&quot;">​</a></h2><blockquote><p>FGO 游戏安装包请查看<a href="./fgo_apk">FGO APK</a></p></blockquote><p>以下列出了 Chaldea app 的 Android、Linux 和 Windows 客户端下载地址，包括 beta 版。</p><p>国内用户若无法直连<strong>Github</strong>下载，请选择 <strong>代理(Proxy)</strong> 链接进行下载。</p><p>所有历史发布版本请见<a href="https://github.com/chaldea-center/chaldea/releases" target="_blank" rel="noreferrer">Github Releases</a></p><p>注意: <code>beta</code>版即预览版，随最新版代码一起更新。一般情况下下载 v2.x 最新正式版即可。</p><p>最新稳定版下载地址:</p><ul><li>Android: <a href="https://worker-cn.chaldea.center/releases/latest/android" target="_blank" rel="noreferrer">https://worker-cn.chaldea.center/releases/latest/android</a></li><li>Windows: <a href="https://worker-cn.chaldea.center/releases/latest/windows" target="_blank" rel="noreferrer">https://worker-cn.chaldea.center/releases/latest/windows</a></li><li>Linux: <a href="https://worker-cn.chaldea.center/releases/latest/linux" target="_blank" rel="noreferrer">https://worker-cn.chaldea.center/releases/latest/linux</a></li></ul>',51)),s(a,{lang:"zh"})]))}});export{c as __pageData,h as default};
